async function draftScopes(t){
 const f=await setup(t),post=async(path,body)=>{const r=await fetch(f.origin+path,{method:'POST',headers:{origin:f.origin,'Content-Type':'application/json'},body:JSON.stringify({command_id:crypto.randomUUID(),...body})});assert.equal(r.status,200);return r.json();};
 const w=(await post('/api/sites/workspaces',{name:'合成客户 A'})).id,w2=(await post('/api/sites/workspaces',{name:'合成客户 B'})).id;
 const account=async(ws,name)=>(await post('/api/sites/workspaces/'+ws+'/accounts',{display_name:name,platform:'facebook',external_identity:null})).id;
 return {...f,w,w2,a:await account(w,'账号 A1'),b:await account(w,'账号 A2'),c:await account(w2,'账号 B1')};
}
async function draftBrowser(t,f,viewport={width:1440,height:1000}){
 const browser=await chromium.launch({executablePath:process.env.PUBLISHER_TEST_BROWSER_PATH||'/usr/bin/chromium',headless:true});t.after(()=>browser.close());const context=await browser.newContext({viewport}),outside=[],errors=[];
 await context.route('**/*',r=>new URL(r.request().url()).origin===f.origin?r.continue():(outside.push(r.request().url()),r.abort()));const page=await context.newPage();page.setDefaultTimeout(8000);page.on('pageerror',e=>errors.push(e.message));await page.goto(f.origin);await page.locator('#account option[value="'+f.a+'"]').waitFor({state:'attached'});await page.locator('#new-content:not([disabled])').waitFor();
 t.after(()=>{assert.deepEqual(outside,[]);assert.deepEqual(errors,[]);});return page;
}
async function fillDraft(page,label){for(const [key,value] of Object.entries({content_id:'SYNTHETIC-20261022-'+label,slug:label.toLowerCase(),title:label,body:label+' 完整正文',platform_body:label+' 平台正文'}))await page.locator('#content-form [name='+key+']').fill(value);}
