test('late platform save cannot clear another platform draft or change its original base',{timeout:40000},async t=>{
 const f=await variantUi(t),page=await draftBrowser(t,f);await page.locator('[data-edit-variant]').click();await page.locator('#variant-body').fill('FB save held after commit');let release,started;const gate=new Promise(r=>{release=r;}),held=new Promise(r=>{started=r;});t.after(()=>release());
 await page.route(/\/variants\?accountId=/,async route=>{if(route.request().method()!=='POST')return route.continue();const r=await route.fetch();assert.equal(r.status(),200);started();await boundedGate(gate);await route.fulfill({response:r});});await page.locator('#variant-save').click();await held;await page.locator('#variant-platform').selectOption('xiaohongshu');await page.locator('#variant-body').fill('XHS unsaved survives older FB response');const reply=page.waitForResponse(r=>r.url().includes('/variants?')&&r.request().method()==='POST');release();await reply;await page.waitForTimeout(150);assert.equal(await page.locator('#variant-platform').inputValue(),'xiaohongshu');assert.equal(await page.locator('#variant-body').inputValue(),'XHS unsaved survives older FB response');assert.match(await page.locator('#variant-source').innerText(),/基础版本 1/);assert.equal(await page.locator('#variant-save').isDisabled(),false);
});

