test('returning to the original pending platform unlocks its own completed save without losing other drafts',{timeout:40000},async t=>{
 const f=await variantUi(t),page=await draftBrowser(t,f);await page.locator('[data-edit-variant]').click();await page.locator('#variant-body').fill('Original platform committed while switching');let release,started;const gate=new Promise(r=>{release=r;}),held=new Promise(r=>{started=r;});t.after(()=>release());
 await page.route(/\/variants\?accountId=/,async route=>{if(route.request().method()!=='POST')return route.continue();const r=await route.fetch();assert.equal(r.status(),200);started();await boundedGate(gate);await route.fulfill({response:r});});await page.locator('#variant-save').click();await held;await page.locator('#variant-platform').selectOption('xiaohongshu');await page.locator('#variant-body').fill('Other platform remains unsaved');await page.locator('#variant-platform').selectOption('facebook');assert.equal(await page.locator('#variant-save').isDisabled(),true);
 const readback=page.waitForResponse(r=>r.url().includes('/variants?')&&r.request().method()==='GET');release();await readback;await page.waitForTimeout(150);assert.equal(await page.locator('#variant-save').isDisabled(),false,'completed original save must unlock when the user returned to that exact draft');assert.equal(await page.locator('#variant-body').isEditable(),true);assert.match(await page.locator('#variant-source').innerText(),/基础版本 2/);assert.equal(await page.locator('#variant-body').inputValue(),'Original platform committed while switching');await page.locator('#variant-platform').selectOption('xiaohongshu');assert.equal(await page.locator('#variant-body').inputValue(),'Other platform remains unsaved');assert.equal(f.db.sql.prepare('SELECT count(*) n FROM sites_content_edits').get().n,1);
});

test('lost variant save acknowledgement retains exact command and explicit retry reads historical commit',{timeout:40000},async t=>{
 const f=await variantUi(t),page=await draftBrowser(t,f);await page.locator('[data-edit-variant]').click();await page.locator('#variant-body').fill('Committed FB edit');let lost=false;await page.route(/\/variants\?accountId=/,async route=>{if(route.request().method()!=='POST'||lost)return route.continue();const r=await route.fetch();assert.equal(r.status(),200);lost=true;await route.abort();});await page.locator('#variant-save').click();await page.locator('#variant-status').filter({hasText:'保留原命令'}).waitFor();assert.equal(await page.locator('#variant-body').getAttribute('readonly'),'');assert.equal(await page.locator('#variant-rebase').isDisabled(),true);assert.equal(f.db.sql.prepare('SELECT count(*) n FROM sites_content_edits').get().n,1);await page.locator('#variant-save').click();await page.locator('#variant-status').filter({hasText:'已保存独立平台版本 2'}).waitFor();assert.equal(f.db.sql.prepare('SELECT count(*) n FROM sites_content_edits').get().n,1);assert.equal(await page.locator('#variant-body').isEditable(),true);
});

test('pending rebase excludes concurrent save and later lost acknowledgement recovers the original receipt',{timeout:40000},async t=>{
 const f=await variantUi(t),page=await draftBrowser(t,f);await page.locator('[data-edit-variant]').click();await page.locator('#variant-body').fill('Rebased FB edit survives lost acknowledgement');
 let release,started,holdRead=true,lost=false;const saves=[],gate=new Promise(r=>{release=r;}),held=new Promise(r=>{started=r;});t.after(()=>release());
 await page.route(/\/variants\?accountId=/,async route=>{
  if(route.request().method()==='GET'&&holdRead){holdRead=false;started();await boundedGate(gate);return route.continue();}
  if(route.request().method()==='POST'){saves.push({url:route.request().url(),body:route.request().postDataJSON()});if(!lost){const r=await route.fetch();assert.equal(r.status(),200);lost=true;return route.abort();}}
  return route.continue();
 });
 await page.locator('#variant-rebase').click();await held;
 // requestSubmit also exercises keyboard/programmatic submission while the GET is held.
 await page.locator('#variant-form').evaluate(form=>form.requestSubmit());await page.waitForTimeout(150);
 assert.equal(saves.length,0,'A rebase in flight must not dispatch a save with a mutable request base');assert.equal(f.db.sql.prepare('SELECT count(*) n FROM sites_content_edits').get().n,0);assert.equal(await page.locator('#variant-save').isDisabled(),true);
 release();await page.locator('#variant-status').filter({hasText:'已读取最新基础版本'}).waitFor();assert.equal(await page.locator('#variant-body').inputValue(),'Rebased FB edit survives lost acknowledgement');
 await page.locator('#variant-save').click();await page.locator('#variant-status').filter({hasText:'保留原命令'}).waitFor();assert.equal(await page.locator('#variant-rebase').isDisabled(),true);await page.locator('#variant-save').click();await page.locator('#variant-status').filter({hasText:'已保存独立平台版本 2'}).waitFor();assert.equal(saves.length,2);assert.deepEqual(saves[0],saves[1]);assert.equal(f.db.sql.prepare('SELECT count(*) n FROM sites_content_edits').get().n,1);
});

