 await page.reload();await page.locator('[data-tab=content]').click();await page.locator('#target-account').selectOption(f.a);await page.locator('[data-content="'+row.id+'"] [data-freeze]').waitFor();assert.equal(await page.locator('[data-content="'+row.id+'"] [data-freeze]').isDisabled(),true);await page.locator('[data-content="'+row.id+'"] [data-preview]').click();await page.locator('#preview-body').filter({hasText:'新平台文字'}).waitFor();await page.locator('#close-preview').click();await page.locator('[data-tab=review]').click();await page.locator('[data-review]').click();await page.locator('#approval-state').filter({hasText:'REVOKED'}).waitFor();assert.equal(await page.locator('[data-decision=APPROVE]').count(),0);
