 if(process.env.V3_SITES_EVIDENCE_DIR){mkdirSync(process.env.V3_SITES_EVIDENCE_DIR,{recursive:true});await page.screenshot({path:join(process.env.V3_SITES_EVIDENCE_DIR,name+'-edited-review-pending.png'),fullPage:true});}
 for(const c of await page.locator('[data-check]').all())await c.check();await page.locator('#approval-reason').fill('重新检查合成新版文字与媒体，独立内容批准');await page.locator('[data-decision=APPROVE]').click();await page.locator('#prepare-plan').click();await page.locator('#plan-state').filter({hasText:'UPLOAD_PREVIEW_ONLY'}).waitFor();assert.match(await page.locator('#preview-body').innerText(),/重新校验后的明确标题/);assert.match(await page.locator('#preview-body').innerText(),/末段仍完整/);await page.waitForFunction(()=>document.querySelector('#preview video')?.readyState>=2);
 const p=f.db.sql.prepare('SELECT * FROM sites_upload_plans WHERE review_id<>?').get(f.sourceId);assert.ok(p);assert.deepEqual(f.db.sql.prepare('SELECT * FROM sites_approval_events WHERE review_id=?').all(f.sourceId),oldEvents);assert.equal(f.db.sql.prepare("SELECT count(*) n FROM publisher_jobs WHERE state<>'DRAFT'").get().n,0);
