test('mobile derived frozen copy supports three edit-inspect-approve-freeze cycles and persistent exact history',{timeout:60000},async t=>{
 const f=await openEditedReviewDraft(t,{width:390,height:844}),{page}=f,seen=[];
 for(let n=1;n<=3;n++){
  if(n>1){await page.locator('#close-preview').click();await page.locator('[data-tab=content]').click();await page.locator('[data-content="'+seen.at(-1).content_id+'"] [data-edit-variant]').click();await page.locator('#variant-form:not([hidden])').waitFor();await page.locator('#variant-title').fill('连续修改标题 '+n);await page.locator('#variant-body').fill('派生稿第 '+n+' 次修改。\n完整末段与原媒体待独立核对。');await page.locator('#variant-save').click();await page.locator('#variant-status').filter({hasText:'已保存独立平台版本 2'}).waitFor();}
  await page.locator('#variant-review:not([disabled])').click();await page.locator('#approval-state').filter({hasText:'PENDING'}).waitFor();await page.waitForFunction(()=>document.querySelector('#preview video')?.readyState>=2);assert.equal(f.variantInspector.calls,n);assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1&&document.querySelector('#preview').scrollWidth<=document.querySelector('#preview').clientWidth+1));
  if(n===3&&process.env.V3_SITES_EVIDENCE_DIR){mkdirSync(process.env.V3_SITES_EVIDENCE_DIR,{recursive:true});await page.screenshot({path:join(process.env.V3_SITES_EVIDENCE_DIR,'mobile-third-derived-review-pending.png'),fullPage:true});}
  for(const c of await page.locator('[data-check]').all())await c.check();await page.locator('#approval-reason').fill('第 '+n+' 轮独立批准，未授予发布许可');await page.locator('[data-decision=APPROVE]').click();await page.locator('#prepare-plan').click();await page.locator('#plan-state').filter({hasText:'UPLOAD_PREVIEW_ONLY'}).waitFor();const plans=f.db.sql.prepare('SELECT * FROM sites_upload_plans WHERE review_id<>?').all(f.sourceId),p=plans.find(p=>!seen.some(s=>s.id===p.id));assert.ok(p);seen.push(p);if(n>1)assert.match(await page.locator('#preview-body').innerText(),new RegExp('派生稿第 '+n+' 次修改'));
 }
 await page.waitForFunction(()=>document.querySelector('#preview video')?.readyState>=2);await page.locator('#preview video').evaluate(async v=>{v.muted=true;await v.play();});await page.waitForFunction(()=>document.querySelector('#preview video')?.currentTime>0);await page.locator('#preview video').evaluate(v=>v.pause());if(process.env.V3_SITES_EVIDENCE_DIR)await page.screenshot({path:join(process.env.V3_SITES_EVIDENCE_DIR,'mobile-third-derived-review-frozen.png'),fullPage:true});
 assert.equal(new Set(seen.map(p=>p.job_id)).size,3);assert.equal(f.db.sql.prepare("SELECT count(*) n FROM publisher_jobs WHERE state<>'DRAFT'").get().n,0);assert.equal(f.db.sql.prepare("SELECT count(*) n FROM sites_approval_events WHERE kind='CONTENT_APPROVED'").get().n,4);
 await page.reload();await page.locator('[data-tab=tasks]').click();await page.locator('[data-task="'+seen.at(-1).job_id+'"] [data-task-preview]').click();await page.locator('#preview-body').filter({hasText:'派生稿第 3 次修改'}).waitFor();await page.locator('#close-preview').click();await page.locator('[data-task="'+seen[0].job_id+'"] [data-task-preview]').click();await page.locator('#preview-body').filter({hasText:'修改后的完整平台正文'}).waitFor();assert.match(await page.locator('#plan-state').innerText(),/STALE_PREVIEW/);
});

async function batchUi(t){
 const f=await draftScopes(t),post=async(input)=>{const response=await fetch(f.origin+'/api/sites/workspaces/'+f.w+'/contents',{method:'POST',headers:{origin:f.origin,'Content-Type':'application/json'},body:JSON.stringify({command_id:crypto.randomUUID(),account_id:f.a,content_id:'SYNTHETIC-BATCH-20261022',slug:input.slug,revision:1,title:input.title,body:'完整原正文与末段保留。',variants:input.variants})});assert.equal(response.status,200);return response.json();};
 const good=[];for(const n of [1,2])good.push(await post({slug:'good-'+n,title:'可用稿 '+n,variants:{facebook:{title:'FB '+n,body:'Facebook 完整正文 '+n},xiaohongshu:{title:'XHS '+n,body:'小红书独立完整正文 '+n}}}));const missing=await post({slug:'missing',title:'仅小红书稿',variants:{xiaohongshu:{title:'XHS',body:'不能借用这篇文字'}}});return {...f,good,missing};
}
for(const [name,viewport] of [['desktop',{width:1440,height:1000}],['mobile',{width:390,height:844}]])test(name+' batch select mixed copies -> preflight -> per-item frozen receipts and clear',{timeout:40000},async t=>{
 const f=await batchUi(t),page=await draftBrowser(t,f,viewport);await page.locator('#batch-select').click();assert.equal(await page.locator('#batch-count').innerText(),'已选 3 / 20');assert.equal(await page.locator('#batch-check').isDisabled(),true);
 await page.locator('#target-account').selectOption(f.b);await page.locator('[data-pick]').first().waitFor();assert.equal(await page.locator('#batch-count').innerText(),'已选 0 / 20');await page.locator('#batch-select').click();await page.locator('#batch-check').dblclick();await page.locator('#batch-results').getByText('缺少所选平台稿，不借用其他平台',{exact:true}).waitFor();assert.equal(await page.locator('[data-batch-result]').count(),3);
 if(process.env.V3_SITES_EVIDENCE_DIR){mkdirSync(process.env.V3_SITES_EVIDENCE_DIR,{recursive:true});await page.screenshot({path:join(process.env.V3_SITES_EVIDENCE_DIR,name+'-batch-preflight.png'),fullPage:true});}
 await page.locator('#batch-freeze').dblclick();await page.locator('#status').filter({hasText:'批次已逐项处理'}).waitFor();assert.equal(f.db.sql.prepare('SELECT count(*) n FROM publisher_jobs').get().n,2);assert.equal(f.db.sql.prepare('SELECT count(*) n FROM publisher_jobs WHERE account_id=?').get(f.b).n,2);assert.equal(await page.locator('#batch-results').getByText('草稿已冻结',{exact:true}).count(),2);assert.equal(await page.locator('#batch-freeze').isDisabled(),true);
 await page.locator('#batch-check').click();await page.locator('#batch-results').getByText('已有冻结任务，保留原回执',{exact:true}).first().waitFor();assert.equal(await page.locator('#batch-freeze').isDisabled(),true);assert.equal(f.db.sql.prepare('SELECT count(*) n FROM sites_execution_claims').get().n,0);
 assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));if(process.env.V3_SITES_EVIDENCE_DIR)await page.screenshot({path:join(process.env.V3_SITES_EVIDENCE_DIR,name+'-batch-receipts.png'),fullPage:true});
 await page.locator('#batch-clear').click();assert.equal(await page.locator('[data-pick]:checked').count(),0);assert.equal(await page.locator('[data-batch-result]').count(),0);await page.locator('[data-tab=tasks]').click();assert.equal(await page.locator('[data-task]').count(),2);await page.locator('[data-task-preview]').first().click();assert.match(await page.locator('#preview-body').innerText(),/Facebook 完整正文/);
 await page.reload();await page.locator('[data-task]').first().waitFor({state:'attached'});assert.equal(await page.locator('[data-task]').count(),2);assert.equal(await page.locator('nav [data-tab]').count(),10);
});
for(const switchTo of ['platform','account','workspace','clear'])test('late batch preflight cannot restore selection after '+switchTo,{timeout:40000},async t=>{
 const f=await batchUi(t),page=await draftBrowser(t,f,{width:390,height:844});await page.locator('#target-account').selectOption(f.a);await page.locator('[data-pick]').first().waitFor();await page.locator('#batch-select').click();let release,started;const gate=new Promise(r=>release=r),held=new Promise(r=>started=r);t.after(()=>release());await page.route('**/task-preflight',async route=>{const response=await route.fetch();started();await boundedGate(gate);await route.fulfill({response});});await page.locator('#batch-check').click();await held;
 if(switchTo==='platform')await page.locator('#content-platform').selectOption('xiaohongshu');if(switchTo==='account')await page.locator('#account').selectOption(f.b);if(switchTo==='workspace')await page.locator('#workspace').selectOption(f.w2);if(switchTo==='clear')await page.locator('#batch-clear').click();const reply=page.waitForResponse(r=>r.url().endsWith('/task-preflight'));release();await reply;await page.waitForTimeout(100);assert.equal(await page.locator('[data-batch-result]').count(),0);assert.equal(await page.locator('[data-pick]:checked').count(),0);assert.equal(await page.locator('#batch-freeze').isDisabled(),true);assert.equal(f.db.sql.prepare('SELECT count(*) n FROM publisher_jobs').get().n,0);
});
test('batch in-flight committed reply cannot dispatch remaining items after account switch',{timeout:40000},async t=>{
 const f=await batchUi(t),page=await draftBrowser(t,f);await page.locator('#target-account').selectOption(f.a);await page.locator('[data-pick]').first().waitFor();await page.locator('#batch-select').click();await page.locator('#batch-check').click();await page.locator('#batch-freeze:not([disabled])').waitFor();let release,started;const gate=new Promise(r=>release=r),held=new Promise(r=>started=r);t.after(()=>release());let submissions=0;await page.route('**/tasks',async route=>{submissions++;const response=await route.fetch();assert.equal(response.status(),200);started();await boundedGate(gate);await route.fulfill({response});});await page.locator('#batch-freeze').click();await held;await page.locator('#account').selectOption(f.b);const reply=page.waitForResponse(r=>r.url().endsWith('/tasks'));release();await reply;await page.waitForTimeout(150);assert.equal(submissions,1);assert.equal(f.db.sql.prepare('SELECT count(*) n FROM publisher_jobs WHERE account_id=?').get(f.a).n,1);assert.equal(await page.locator('[data-batch-result]').count(),0);assert.equal(await page.locator('[data-task]').count(),0);assert.equal(await page.locator('#account').inputValue(),f.b);
});
test('batch lost acknowledgment and per-item failure preserve committed receipts without retrying the batch',{timeout:40000},async t=>{
 const f=await batchUi(t),page=await draftBrowser(t,f);await page.locator('#target-account').selectOption(f.a);await page.locator('[data-pick]').first().waitFor();await page.locator('#batch-select').click();await page.locator('#batch-check').click();await page.locator('#batch-freeze:not([disabled])').waitFor();let calls=0;
 await page.route('**/tasks',async route=>{calls++;if(calls===1){const response=await route.fetch();assert.equal(response.status(),200);await route.fulfill({status:503,contentType:'application/json',body:JSON.stringify({error:'SYNTHETIC_ACK_LOST'})});}else await route.fulfill({status:409,contentType:'application/json',body:JSON.stringify({error:'SYNTHETIC_WRITE_REJECTED'})});});await page.locator('#batch-freeze').click();await page.locator('#status').filter({hasText:'批次已逐项处理'}).waitFor();assert.equal(calls,2);assert.equal(f.db.sql.prepare('SELECT count(*) n FROM publisher_jobs').get().n,1);assert.match(await page.locator('#batch-results').innerText(),/SYNTHETIC_ACK_LOST/);assert.match(await page.locator('#batch-results').innerText(),/SYNTHETIC_WRITE_REJECTED/);assert.equal(await page.locator('#batch-freeze').isDisabled(),true);
 await page.unroute('**/tasks');await page.locator('#batch-check').click();await page.locator('#batch-results').getByText('已有冻结任务，保留原回执',{exact:true}).waitFor();await page.locator('#batch-freeze').click();await page.locator('#status').filter({hasText:'批次已逐项处理'}).waitFor();assert.equal(f.db.sql.prepare('SELECT count(*) n FROM publisher_jobs').get().n,2);
});
test('batch reviewed media returns original task and another target requires independent review',{timeout:40000},async t=>{
 const f=await sharedReviewUi(t),page=await draftBrowser(t,f),pick='[data-pick="'+f.p.content_id+'"]';await page.locator('#target-account').selectOption(f.a);await page.locator(pick).check();await page.locator('#batch-check').click();await page.locator('#batch-results').getByText('已有冻结任务，保留原回执',{exact:true}).waitFor();assert.equal(await page.locator('#batch-freeze').isDisabled(),true);
 await page.locator('#target-account').selectOption(f.b);await page.locator(pick).check();await page.locator('#batch-check').click();await page.locator('#batch-results').getByText('新目标账号须独立审核',{exact:true}).waitFor();assert.equal(await page.locator('#batch-freeze').isDisabled(),true);assert.deepEqual(f.db.sql.prepare('SELECT * FROM sites_approval_events WHERE review_id=?').all(f.sourceId),f.oldEvents);assert.equal(f.db.sql.prepare('SELECT count(*) n FROM publisher_jobs WHERE account_id=?').get(f.b).n,0);
});
test('batch edited reviewed media cannot bypass new inspection or independent approval',{timeout:40000},async t=>{
 const f=await openEditedReviewDraft(t,{width:390,height:844}),page=f.page,edited=f.db.sql.prepare('SELECT content_id FROM sites_content_edits').get().content_id,events=f.db.sql.prepare('SELECT * FROM sites_approval_events ORDER BY sequence').all();await page.locator('#variant-close').click();await page.locator('#target-account').selectOption(f.a);await page.locator('[data-pick="'+edited+'"]').check();await page.locator('#batch-check').click();await page.locator('#batch-results').getByText('编辑稿须重新校验和独立审核',{exact:true}).waitFor();assert.equal(await page.locator('#batch-freeze').isDisabled(),true);assert.deepEqual(f.db.sql.prepare('SELECT * FROM sites_approval_events ORDER BY sequence').all(),events);assert.equal(f.db.sql.prepare('SELECT count(*) n FROM publisher_jobs WHERE content_id=?').get(edited).n,0);
});
